      !> State of nonlocal_pcm
      type(nonlocal_pcm_state), intent(inout) :: state
      !> Direction for v
      real(wp), contiguous, intent(in) :: dv(:, :)
      !> Direction for vn
      real(wp), contiguous, intent(in) :: dvn(:, :)
      !> Hessian times direction, v block
      real(wp), contiguous, intent(out) :: hvp_v(:, :)
      !> Hessian times direction, vn block
      real(wp), contiguous, intent(out) :: hvp_vn(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%ready < 3) then
         call fatal_error(error, "[nonlocal_pcm_mf_response] call nonlocal_pcm_solve first")
         return
      end if
      npt = state%npt
      nblk = size(dv, 2)
      if (any(shape(dv) /= [npt, nblk])) then
         call fatal_error(error, "[nonlocal_pcm_mf_response] dv: wrong shape")
         return
      end if
      if (any(shape(dvn) /= [npt, nblk])) then
         call fatal_error(error, "[nonlocal_pcm_mf_response] dvn: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt, nblk])) then
         call fatal_error(error, "[nonlocal_pcm_mf_response] hvp_v: wrong shape")
         return
      end if
      if (any(shape(hvp_vn) /= [npt, nblk])) then
         call fatal_error(error, "[nonlocal_pcm_mf_response] hvp_vn: wrong shape")
         return
      end if
      do blk = 1, nblk
         call nonlocal_pcm_mf_response_one(state, dv(:, blk), dvn(:, blk), hvp_v(:, blk), &
                                           hvp_vn(:, blk), error)
         if (allocated(error)) return
      end do
   end subroutine nonlocal_pcm_mf_response

